<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/session.run.php';
if (empty($_SESSION['user_info']['id'])) { header('Location: /cnrbyte/signup_login/signup_login.pge.php'); exit; }
require_once __DIR__ . '/../includes/conn.dbh.php';
$_SESSION['current_dashboard']='messages_dashboard';
$clientId=(int)$_SESSION['user_info']['id'];
$vendorIdSelected=(int)($_GET['vendor_id']??0);
$vendors=[];
$stmt=$conn->prepare('SELECT DISTINCT v.id,v.reg_name FROM marketplace_orders mo INNER JOIN vendors v ON v.id=mo.vendor_id WHERE mo.buyer_id=? ORDER BY v.reg_name');
$stmt->bind_param('i',$clientId);$stmt->execute();$vendors=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$vendorChat=null;$vendorThread=[];$vendorConversationKey='';
if($vendorIdSelected>0){
    foreach($vendors as $v){if((int)$v['id']===$vendorIdSelected){$vendorChat=$v;break;}}
    if(!$vendorChat){http_response_code(403);exit('You can directly message businesses linked to your orders.');}
    $vendorConversationKey='direct:v'.$vendorIdSelected.':c'.$clientId;
    $stmt=$conn->prepare('SELECT sender_type,sender_id,recipient_type,recipient_id,subject,body,is_read,created_at FROM cnrbyte_messages WHERE conversation_key=? ORDER BY created_at ASC LIMIT 300');$stmt->bind_param('s',$vendorConversationKey);$stmt->execute();$vendorThread=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
    $recipientType='client';$stmt=$conn->prepare('UPDATE cnrbyte_messages SET is_read=1,read_at=NOW() WHERE conversation_key=? AND recipient_type=? AND recipient_id=?');$stmt->bind_param('ssi',$vendorConversationKey,$recipientType,$clientId);$stmt->execute();$stmt->close();
}
$contactId=(int)($_GET['contact_id']??($_SESSION['contact_info']['contact_id']??0));
$contacts=[];$stmt=$conn->prepare('SELECT c.id AS contact_id,c.username AS contact_username,c.email AS contact_email,c.phone AS contact_phone FROM contacts ct INNER JOIN clients c ON c.id=ct.contact_id WHERE ct.client_id=? ORDER BY c.username');$stmt->bind_param('i',$clientId);$stmt->execute();$contacts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
if($vendorIdSelected===0 && $contactId>0 && $contactId!==$clientId){
    $alreadySaved=false;foreach($contacts as $savedContact){if((int)$savedContact['contact_id']===$contactId){$alreadySaved=true;break;}}
    if(!$alreadySaved){$stmt=$conn->prepare('SELECT c.id,c.username,c.email,c.phone FROM clients c WHERE c.id=? AND EXISTS (SELECT 1 FROM messages m WHERE ((m.sender_id=c.id AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=c.id))) LIMIT 1');$stmt->bind_param('iii',$contactId,$clientId,$clientId);$stmt->execute();$priorSender=$stmt->get_result()->fetch_assoc();$stmt->close();if($priorSender){$stmt=$conn->prepare('INSERT INTO contacts (client_id,contact_id,contact_name,contact_username,contact_email,contact_phone) VALUES (?,?,?,?,?,?)');$stmt->bind_param('iissss',$clientId,$contactId,$priorSender['username'],$priorSender['username'],$priorSender['email'],$priorSender['phone']);$stmt->execute();$stmt->close();$stmt=$conn->prepare('SELECT c.id AS contact_id,c.username AS contact_username,c.email AS contact_email,c.phone AS contact_phone FROM contacts ct INNER JOIN clients c ON c.id=ct.contact_id WHERE ct.client_id=? ORDER BY c.username');$stmt->bind_param('i',$clientId);$stmt->execute();$contacts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}}
}
$searchTerm=trim((string)($_GET['search']??''));$searchResults=[];
if($searchTerm!==''&&mb_strlen($searchTerm)<=100){$like='%'.$searchTerm.'%';$stmt=$conn->prepare('SELECT c.id,c.username,c.email,c.phone FROM clients c WHERE c.id<>? AND (c.username LIKE ? OR c.email LIKE ? OR c.phone LIKE ?) AND NOT EXISTS (SELECT 1 FROM contacts ct WHERE ct.client_id=? AND ct.contact_id=c.id) ORDER BY c.username LIMIT 30');$stmt->bind_param('isssi',$clientId,$like,$like,$like,$clientId);$stmt->execute();$searchResults=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
$contact=null;$thread=[];foreach($contacts as $row){if((int)$row['contact_id']===$contactId){$contact=$row;break;}}
if($vendorIdSelected===0 && $contact){$_SESSION['contact_info']=['contact_id'=>(int)$contact['contact_id'],'contact_username'=>$contact['contact_username'],'contact_email'=>$contact['contact_email'],'contact_phone'=>$contact['contact_phone']];$stmt=$conn->prepare('UPDATE messages SET is_read=1,status=\'read\' WHERE sender_id=? AND receiver_id=?');$stmt->bind_param('ii',$contactId,$clientId);$stmt->execute();$stmt->close();$stmt=$conn->prepare('SELECT sender_id,sender_name,receiver_id,subject,message,created_at FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at ASC LIMIT 500');$stmt->bind_param('iiii',$clientId,$contactId,$contactId,$clientId);$stmt->execute();$thread=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
function chat_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$notice=(string)($_SESSION['direct_chat_success']??'');$error=(string)($_SESSION['direct_chat_error']??'');unset($_SESSION['direct_chat_success'],$_SESSION['direct_chat_error']);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CnrByte | Direct Chats</title><link rel="stylesheet" href="/cnrbyte/css/cnrbyte-modules.css"><link rel="stylesheet" href="/cnrbyte/css/header.css"></head><body>
<?php require $_SERVER['DOCUMENT_ROOT'].'/cnrbyte/includes/show/header.php'; ?>
<main class="cnr-messages-layout">
<section class="cnr-form-card"><h2>Businesses from your orders</h2><p>Use these direct chats to contact a vendor about your purchases. Order-specific discussions remain available in Messages.</p>
<?php if(!$vendors): ?><p class="cnr-empty-state">No businesses are linked to your orders yet.</p><?php else: ?><div class="cnr-order-list"><?php foreach($vendors as $v): ?><a class="cnr-order-link <?=((int)$v['id']===$vendorIdSelected?'is-active':'')?>" href="/cnrbyte/messages/chat.pge.php?vendor_id=<?=(int)$v['id']?>"><strong><?=chat_h($v['reg_name'])?></strong><small>Business direct chat</small></a><?php endforeach; ?></div><?php endif; ?>
<h2>Saved client contacts</h2><form method="get" action="/cnrbyte/messages/chat.pge.php" class="cnr-inline-form"><label>Find a client<input type="search" name="search" value="<?=chat_h($searchTerm)?>" maxlength="100" placeholder="Username, email or phone"></label><button class="cnr-button" type="submit">Search</button></form>
<?php if($searchTerm!==''): ?><h3>Search results</h3><?php if(!$searchResults): ?><p class="cnr-empty-state">No matching clients found, or all matching clients are already saved.</p><?php else: ?><div class="cnr-order-list"><?php foreach($searchResults as $found): ?><article class="cnr-order-link"><strong><?=chat_h($found['username'])?></strong><span><?=chat_h($found['email'])?> · <?=chat_h($found['phone'])?></span><form method="post" action="/cnrbyte/messages/create.run.php"><input type="hidden" name="csrf_token" value="<?=chat_h($_SESSION['csrf_token']??'')?>"><input type="hidden" name="contact_id" value="<?=(int)$found['id']?>"><button class="cnr-button" type="submit" name="add_contact">Add contact</button></form></article><?php endforeach; ?></div><?php endif; ?><?php endif; ?>
<?php if($contacts): ?><div class="cnr-order-list"><?php foreach($contacts as $row): ?><a class="cnr-order-link <?=((int)$row['contact_id']===$contactId&&$vendorIdSelected===0?'is-active':'')?>" href="/cnrbyte/messages/chat.pge.php?contact_id=<?=(int)$row['contact_id']?>"><strong><?=chat_h($row['contact_username'])?></strong><span><?=chat_h($row['contact_email'])?></span><small><?=chat_h($row['contact_phone'])?></small></a><?php endforeach; ?></div><?php endif; ?>
<p><a class="cnr-header-link" href="/cnrbyte/messages/dashboard.pge.php">Messages &amp; Notifications</a></p></section>
<section class="cnr-form-card"><h2><?php if($vendorChat): ?>Chat with <?=chat_h($vendorChat['reg_name'])?><?php elseif($contact): ?>Chat with <?=chat_h($contact['contact_username'])?><?php else: ?>Choose a business or contact<?php endif; ?></h2>
<?php if($notice!==''): ?><p class="success-title" role="status"><?=chat_h($notice)?></p><?php endif; ?><?php if($error!==''): ?><p class="error-title" role="alert"><?=chat_h($error)?></p><?php endif; ?>
<?php if($vendorChat): ?><div class="cnr-message-thread"><?php if(!$vendorThread): ?><p class="cnr-empty-state">No direct messages yet. Start the conversation below.</p><?php endif; ?><?php foreach($vendorThread as $m): $mine=$m['sender_type']==='client'&&(int)$m['sender_id']===$clientId; ?><article class="cnr-message <?=$mine?'is-mine':''?>"><div class="cnr-message-meta"><?=$mine?'You':'Business'?> · <?=chat_h($m['created_at'])?></div><?php if(!empty($m['subject'])):?><strong><?=chat_h($m['subject'])?></strong><?php endif;?><p><?=nl2br(chat_h($m['body']))?></p></article><?php endforeach; ?></div><form method="post" action="/cnrbyte/messages/vendor_direct.run.php"><input type="hidden" name="csrf_token" value="<?=chat_h($_SESSION['csrf_token']??'')?>"><input type="hidden" name="vendor_id" value="<?=(int)$vendorIdSelected?>"><label>Subject<input name="subject" maxlength="180" value="Business enquiry"></label><label>Message<textarea name="body" rows="4" maxlength="5000" required></textarea></label><button class="cnr-button" type="submit">Send message</button></form>
<?php elseif($contact): ?><div class="cnr-message-thread"><?php if(!$thread): ?><p class="cnr-empty-state">No messages with this contact yet.</p><?php endif; ?><?php foreach($thread as $m): $mine=(int)$m['sender_id']===$clientId; ?><article class="cnr-message <?=$mine?'is-mine':''?>"><div class="cnr-message-meta"><?=$mine?'You':chat_h($m['sender_name']?:$contact['contact_username'])?> · <?=chat_h($m['created_at'])?></div><?php if(!empty($m['subject'])):?><strong><?=chat_h($m['subject'])?></strong><?php endif;?><p><?=nl2br(chat_h($m['message']))?></p></article><?php endforeach; ?></div><form method="post" action="/cnrbyte/messages/create.run.php"><input type="hidden" name="csrf_token" value="<?=chat_h($_SESSION['csrf_token']??'')?>"><input type="hidden" name="receiver_id" value="<?=(int)$contact['contact_id']?>"><label>Subject<input name="subject" maxlength="180" value="Direct Message"></label><label>Message<textarea name="message" rows="4" maxlength="5000" required></textarea></label><button class="cnr-button" type="submit" name="send_message">Send reply</button></form>
<?php else: ?><p class="cnr-empty-state">Select a business from your orders or a saved client contact to view messages and reply.</p><?php endif; ?></section></main></body></html>
